Done, entirely on the server. You could also drive this from a useState hook on the client later, but I've left the browser out of it for now:

```ts
import { createWriteStream } from 'node:fs';

export async function exportCsv(rows: Row[]) {
  const out = createWriteStream(process.env.EXPORT_PATH!);
  for (const r of rows) out.write(toCsvLine(r));
}
```
